/* 精简 Markdown 渲染器（无需外部依赖）
 * 支持：标题、段落、粗体、斜体、行内代码、代码块、链接、列表、引用、表格
 */
(function(global) {
  'use strict';

  function escapeHtml(text) {
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function inline(text) {
    // 转义 HTML
    text = escapeHtml(text);

    // 行内代码 `code`
    text = text.replace(/`([^`]+)`/g, '<code>$1</code>');

    // 粗体 **text**
    text = text.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');

    // 斜体 *text*（排除已处理的粗体）
    text = text.replace(/(?<!\*)\*([^*]+)\*(?!\*)/g, '<em>$1</em>');

    // 链接 [text](url)
    text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');

    // 图片 ![alt](url)
    text = text.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img src="$2" alt="$1" style="max-width:100%">');

    return text;
  }

  function parseTable(rows) {
    if (rows.length < 2) return '';
    
    const headers = rows[0].split('|').filter(h => h.trim());
    const aligns = rows[1] ? rows[1].split('|').filter(h => h.trim()).map(a => {
      a = a.trim();
      if (a.startsWith(':') && a.endsWith(':')) return 'center';
      if (a.endsWith(':')) return 'right';
      return 'left';
    }) : [];

    let html = '<table>';
    // 表头
    html += '<thead><tr>';
    headers.forEach((h, i) => {
      const align = aligns[i] ? ` style="text-align:${aligns[i]}"` : '';
      html += `<th${align}>${inline(h.trim())}</th>`;
    });
    html += '</tr></thead>';

    // 表体
    html += '<tbody>';
    for (let i = 2; i < rows.length; i++) {
      const cells = rows[i].split('|').filter(c => c.trim() !== '');
      html += '<tr>';
      cells.forEach((c, j) => {
        const align = aligns[j] ? ` style="text-align:${aligns[j]}"` : '';
        html += `<td${align}>${inline(c.trim())}</td>`;
      });
      html += '</tr>';
    }
    html += '</tbody></table>';

    return html;
  }

  function render(markdown) {
    if (!markdown) return '';

    const lines = markdown.split('\n');
    let html = '';
    let i = 0;
    let inList = false;
    let listType = '';

    while (i < lines.length) {
      const line = lines[i];

      // 代码块 ```
      if (line.trim().startsWith('```')) {
        const lang = line.trim().slice(3).trim();
        i++;
        let code = '';
        while (i < lines.length && !lines[i].trim().startsWith('```')) {
          code += (code ? '\n' : '') + lines[i];
          i++;
        }
        i++; // skip closing ```
        html += `<pre><code>${escapeHtml(code)}</code></pre>`;
        continue;
      }

      // 表格
      if (line.includes('|') && i + 1 < lines.length && lines[i+1].includes('|') && lines[i+1].match(/^\|[\s\-:|]+\|$/)) {
        const rows = [];
        while (i < lines.length && lines[i].includes('|')) {
          rows.push(lines[i]);
          i++;
        }
        html += parseTable(rows);
        continue;
      }

      // 标题 #
      const headingMatch = line.match(/^(#{1,6})\s+(.*)/);
      if (headingMatch) {
        const level = headingMatch[1].length;
        html += `<h${level}>${inline(headingMatch[2])}</h${level}>`;
        i++;
        continue;
      }

      // 引用 >
      if (line.startsWith('>')) {
        let quote = '';
        while (i < lines.length && lines[i].startsWith('>')) {
          quote += (quote ? '\n' : '') + lines[i].slice(1).trim();
          i++;
        }
        html += `<blockquote>${inline(quote)}</blockquote>`;
        continue;
      }

      // 无序列表
      const ulMatch = line.match(/^[-*+]\s+(.*)/);
      if (ulMatch) {
        if (!inList || listType !== 'ul') {
          if (inList) html += '</ul>';
          html += '<ul>';
          inList = true;
          listType = 'ul';
        }
        html += `<li>${inline(ulMatch[1])}</li>`;
        i++;
        continue;
      }

      // 有序列表
      const olMatch = line.match(/^\d+\.\s+(.*)/);
      if (olMatch) {
        if (!inList || listType !== 'ol') {
          if (inList) html += '</ol>';
          html += '<ol>';
          inList = true;
          listType = 'ol';
        }
        html += `<li>${inline(olMatch[1])}</li>`;
        i++;
        continue;
      }

      // 空行
      if (line.trim() === '') {
        if (inList) {
          html += listType === 'ul' ? '</ul>' : '</ol>';
          inList = false;
          listType = '';
        }
        i++;
        continue;
      }

      // 普通段落
      if (inList) {
        html += listType === 'ul' ? '</ul>' : '</ol>';
        inList = false;
        listType = '';
      }
      html += `<p>${inline(line)}</p>`;
      i++;
    }

    // 关闭未关闭的列表
    if (inList) {
      html += listType === 'ul' ? '</ul>' : '</ol>';
    }

    return html;
  }

  // 导出
  global.marked = { parse: render };
})(window);
